fn min_inspectors(n: i8, d: i8) -> i8 {
    // Each inspector covers (2*d + 1) items.
    let coverage = 2 * d + 1;
    // Compute the ceiling of n / coverage:
    // ceil(n / coverage) = (n + coverage - 1) / coverage
    (n + coverage - 1) / coverage
}

